import sys

class Solution:
    def evaluate(self, expr: str) -> int:
        sys.setrecursionlimit(100000)
        s = expr.replace(" ", "")
        i = 0
        def expression():
            nonlocal i
            sign = 1
            if i < len(s) and s[i] == "-":
                sign, i = -1, i + 1
            total = sign * term()
            while i < len(s) and s[i] in "+-":
                op = s[i]
                i += 1
                total = total + term() if op == "+" else total - term()
            return total
        def term():
            nonlocal i
            value = factor()
            while i < len(s) and s[i] in "*/":
                op = s[i]
                i += 1
                rhs = factor()
                if op == "*":
                    value *= rhs
                else:
                    q = abs(value) // abs(rhs)
                    value = q if (value < 0) == (rhs < 0) else -q
            return value
        def factor():
            nonlocal i
            if s[i] == "(":
                i += 1
                value = expression()
                i += 1
                return value
            value = 0
            while i < len(s) and s[i].isdigit():
                value = value * 10 + int(s[i])
                i += 1
            return value
        return expression()

