class Solution {
    private String s;
    private int i;

    public int evaluate(String expr) {
        s = expr.replace(" ", "");
        i = 0;
        return expression();
    }

    private int expression() {
        int sign = 1;
        if (i < s.length() && s.charAt(i) == '-') { sign = -1; i++; }
        int total = sign * term();
        while (i < s.length() && (s.charAt(i) == '+' || s.charAt(i) == '-')) {
            char op = s.charAt(i++);
            total = op == '+' ? total + term() : total - term();
        }
        return total;
    }

    private int term() {
        int value = factor();
        while (i < s.length() && (s.charAt(i) == '*' || s.charAt(i) == '/')) {
            char op = s.charAt(i++);
            int rhs = factor();
            value = op == '*' ? value * rhs : value / rhs;
        }
        return value;
    }

    private int factor() {
        if (s.charAt(i) == '(') {
            i++;
            int value = expression();
            i++;
            return value;
        }
        int value = 0;
        while (i < s.length() && Character.isDigit(s.charAt(i))) value = value * 10 + (s.charAt(i++) - '0');
        return value;
    }
}

