static const char* src;
static int pos;
static int expression(void);

static void skip(void) { while (src[pos] == ' ') pos++; }

static int factor(void) {
    skip();
    if (src[pos] == '(') {
        pos++;
        int value = expression();
        skip();
        pos++;
        return value;
    }
    int value = 0;
    while (src[pos] >= '0' && src[pos] <= '9') value = value * 10 + (src[pos++] - '0');
    return value;
}

static int term(void) {
    int value = factor();
    for (skip(); src[pos] == '*' || src[pos] == '/'; skip()) {
        char op = src[pos++];
        int rhs = factor();
        value = op == '*' ? value * rhs : value / rhs;
    }
    return value;
}

static int expression(void) {
    skip();
    int sign = 1;
    if (src[pos] == '-') { sign = -1; pos++; }
    int total = sign * term();
    for (skip(); src[pos] == '+' || src[pos] == '-'; skip()) {
        char op = src[pos++];
        total = op == '+' ? total + term() : total - term();
    }
    return total;
}

int evaluate(char* expr) {
    src = expr;
    pos = 0;
    return expression();
}

