class Solution:
    def evaluate(self, expr: str) -> int:
        frames = []
        terms, op, num = [], "+", 0
        for c in expr + "#":
            if c == " ":
                continue
            if c.isdigit():
                num = num * 10 + int(c)
                continue
            if c == "(":
                frames.append((terms, op))
                terms, op, num = [], "+", 0
                continue
            if op == "+":
                terms.append(num)
            elif op == "-":
                terms.append(-num)
            elif op == "*":
                terms[-1] *= num
            else:
                q = abs(terms[-1]) // abs(num)
                terms[-1] = q if (terms[-1] < 0) == (num < 0) else -q
            if c == ")":
                num = sum(terms)
                terms, op = frames.pop()
            else:
                op, num = c, 0
        return sum(terms)

