class Solution {
    public int evaluate(String expr) {
        int n = expr.length();
        int[] terms = new int[n + 1];
        int[] frameStart = new int[n + 1];
        char[] frameOp = new char[n + 1];
        int top = 0, frames = 0, num = 0, start = 0;
        char op = '+';
        for (int i = 0; i <= n; i++) {
            char c = i < n ? expr.charAt(i) : '#';
            if (c == ' ') continue;
            if (Character.isDigit(c)) { num = num * 10 + (c - '0'); continue; }
            if (c == '(') {
                frameStart[frames] = start;
                frameOp[frames++] = op;
                start = top;
                op = '+';
                num = 0;
                continue;
            }
            if (op == '+') terms[top++] = num;
            else if (op == '-') terms[top++] = -num;
            else if (op == '*') terms[top - 1] *= num;
            else terms[top - 1] /= num;
            if (c == ')') {
                num = 0;
                for (int k = start; k < top; k++) num += terms[k];
                top = start;
                start = frameStart[--frames];
                op = frameOp[frames];
            } else {
                op = c;
                num = 0;
            }
        }
        int sum = 0;
        for (int k = 0; k < top; k++) sum += terms[k];
        return sum;
    }
}

