class Solution {
public:
    int evaluate(string& expr) {
        vector<int> terms;
        vector<pair<size_t, char>> frames;
        size_t start = 0;
        int num = 0;
        char op = '+';
        for (size_t i = 0; i <= expr.size(); i++) {
            char c = i < expr.size() ? expr[i] : '#';
            if (c == ' ') continue;
            if (isdigit(c)) { num = num * 10 + (c - '0'); continue; }
            if (c == '(') {
                frames.push_back({start, op});
                start = terms.size();
                op = '+';
                num = 0;
                continue;
            }
            if (op == '+') terms.push_back(num);
            else if (op == '-') terms.push_back(-num);
            else if (op == '*') terms.back() *= num;
            else terms.back() /= num;
            if (c == ')') {
                num = accumulate(terms.begin() + start, terms.end(), 0);
                terms.resize(start);
                start = frames.back().first;
                op = frames.back().second;
                frames.pop_back();
            } else {
                op = c;
                num = 0;
            }
        }
        return accumulate(terms.begin(), terms.end(), 0);
    }
};

